"use client";
/* Robo, from the Piixpal shadcn registry. Options: https://piixpal.dvkk.dev/components/ */
import * as React from "react";
import { loadPiixpal, piixAttrs, type PiixProps } from "@/lib/piixpal";

export function Robo(props: PiixProps) {
  React.useEffect(() => { loadPiixpal("robo"); }, []);
  return React.createElement("piix-sprite", { "name": "robo", ...piixAttrs(props) });
}

export default Robo;
